class Solution {
public:
    int minExtraChar(string s, vector<string>& dictionary) {
        int n = s.size();
        // Trie as parallel arrays; node 0 is root, 0 in child slot means "no child".
        vector<array<int,26>> ch;
        vector<int> isEnd;
        ch.push_back(array<int,26>{});
        isEnd.push_back(0);
        for (const string& w : dictionary) {
            int node = 0;
            for (char c : w) {
                int idx = c - 'a';
                if (ch[node][idx] == 0) {
                    ch[node][idx] = (int)ch.size();
                    ch.push_back(array<int,26>{});
                    isEnd.push_back(0);
                }
                node = ch[node][idx];
            }
            isEnd[node] = 1;
        }
        const int INF = 1e9;
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            // Option 1: leave s[i] as an extra character.
            if (dp[i] + 1 < dp[i + 1]) dp[i + 1] = dp[i] + 1;
            // Option 2: match a dictionary word starting at i by walking the trie.
            int node = 0;
            for (int j = i; j < n; j++) {
                int idx = s[j] - 'a';
                int nxt = ch[node][idx];
                if (nxt == 0) break;
                node = nxt;
                if (isEnd[node] && dp[i] < dp[j + 1]) {
                    dp[j + 1] = dp[i];
                }
            }
        }
        return dp[n];
    }
};
